solutions.naive:
class Solution:
    def simplifyPath(self, path: str) -> str:
        parts = [p for p in path.split("/") if p != "" and p != "."]
        changed = True
        while changed:
            changed = False
            for i, part in enumerate(parts):
                if part == "..":
                    start = max(0, i - 1)
                    parts[start:i + 1] = []
                    changed = True
                    break
        return "/" + "/".join(p for p in parts if p != "..")

solutions.better:
class Solution:
    def simplifyPath(self, path: str) -> str:
        stack = []
        for part in path.split("/"):
            if part == "" or part == ".":
                continue
            if part == "..":
                if stack:
                    stack.pop()
            else:
                stack.append(part)
        return "/" + "/".join(stack)

solutions.optimal:
class Solution:
    def simplifyPath(self, path: str) -> str:
        stack = []
        skip = {"", "."}
        for part in path.split("/"):
            if part in skip:
                continue
            if part == "..":
                if stack:
                    stack.pop()
            else:
                # Names like "..." are valid directory names.
                stack.append(part)
        return "/" + "/".join(stack)

